package mapx

import (
	"fmt"
	"strconv"
	"strings"
)

type segment struct {
	key     string
	index   int
	isIndex bool
}

func parsePath(path string) ([]segment, error) {
	if path == "" {
		return nil, fmt.Errorf("%w: empty path", ErrInvalidPath)
	}

	var segs []segment
	for i := 0; i < len(path); {
		if path[i] == '[' {
			end := strings.IndexByte(path[i:], ']')
			if end < 0 {
				return nil, fmt.Errorf("%w: unclosed '[' in %q", ErrInvalidPath, path)
			}
			digits := path[i+1 : i+end]
			n, err := strconv.Atoi(digits)
			if err != nil || n < 0 {
				return nil, fmt.Errorf("%w: bad index %q", ErrInvalidPath, digits)
			}
			segs = append(segs, segment{index: n, isIndex: true})
			i += end + 1
		} else {
			start := i
			for i < len(path) && path[i] != '.' && path[i] != '[' {
				i++
			}
			if start == i {
				return nil, fmt.Errorf("%w: empty key in %q", ErrInvalidPath, path)
			}
			segs = append(segs, segment{key: path[start:i]})
		}

		if i < len(path) && path[i] == '.' {
			i++
			if i == len(path) {
				return nil, fmt.Errorf("%w: trailing '.' in %q", ErrInvalidPath, path)
			}
		}
	}
	return segs, nil
}

type mapRef interface {
	set(key string, value interface{})
	lookup(key string) (interface{}, bool)
	remove(key string)
}

type stdMap map[string]interface{}

func (m stdMap) set(key string, value interface{})      { m[key] = value }
func (m stdMap) lookup(key string) (interface{}, bool)  { v, ok := m[key]; return v, ok }
func (m stdMap) remove(key string)                      { delete(m, key) }

type namedMap Map

func (m namedMap) set(key string, value interface{})     { m[key] = value }
func (m namedMap) lookup(key string) (interface{}, bool) { v, ok := m[key]; return v, ok }
func (m namedMap) remove(key string)                     { delete(m, key) }

func asMapRef(v interface{}) (mapRef, bool) {
	switch m := v.(type) {
	case map[string]interface{}:
		return stdMap(m), true
	case Map:
		return namedMap(m), true
	default:
		return nil, false
	}
}

func asSlice(v interface{}) ([]interface{}, bool) {
	s, ok := v.([]interface{})
	return s, ok
}

func createContainer(next segment) interface{} {
	if next.isIndex {
		return make([]interface{}, next.index+1)
	}
	return map[string]interface{}{}
}

func lookup(root Map, path string) (interface{}, error) {
	segs, err := parsePath(path)
	if err != nil {
		return nil, err
	}

	var cur interface{} = map[string]interface{}(root)
	for _, s := range segs {
		if s.isIndex {
			sl, ok := asSlice(cur)
			if !ok {
				return nil, fmt.Errorf("%w: expected slice for index [%d], got %T", ErrTypeMismatch, s.index, cur)
			}
			if s.index >= len(sl) {
				return nil, fmt.Errorf("%w: index [%d] out of range", ErrNotFound, s.index)
			}
			cur = sl[s.index]
		} else {
			m, ok := asMapRef(cur)
			if !ok {
				return nil, fmt.Errorf("%w: expected map for key %q, got %T", ErrTypeMismatch, s.key, cur)
			}
			v, ok := m.lookup(s.key)
			if !ok {
				return nil, fmt.Errorf("%w: key %q", ErrNotFound, s.key)
			}
			cur = v
		}
	}
	return cur, nil
}

func assign(root Map, path string, value interface{}) error {
	segs, err := parsePath(path)
	if err != nil {
		return err
	}
	return assignNode(map[string]interface{}(root), segs, value)
}

func assignNode(node interface{}, segs []segment, value interface{}) error {
	s := segs[0]
	rest := segs[1:]

	if s.isIndex {
		sl, ok := asSlice(node)
		if !ok {
			return fmt.Errorf("%w: cannot index %T", ErrTypeMismatch, node)
		}
		if s.index >= len(sl) {
			return fmt.Errorf("%w: index [%d] out of range", ErrNotFound, s.index)
		}
		if len(rest) == 0 {
			sl[s.index] = value
			return nil
		}
		if sl[s.index] == nil {
			sl[s.index] = createContainer(rest[0])
		}
		return assignNode(sl[s.index], rest, value)
	}

	m, ok := asMapRef(node)
	if !ok {
		return fmt.Errorf("%w: cannot set key %q on %T", ErrTypeMismatch, s.key, node)
	}
	if len(rest) == 0 {
		m.set(s.key, value)
		return nil
	}
	child, exists := m.lookup(s.key)
	if !exists || child == nil {
		child = createContainer(rest[0])
		m.set(s.key, child)
	}
	return assignNode(child, rest, value)
}

func remove(root Map, path string) error {
	segs, err := parsePath(path)
	if err != nil {
		return err
	}
	return removeNode(map[string]interface{}(root), segs)
}

func removeNode(node interface{}, segs []segment) error {
	s := segs[0]
	rest := segs[1:]

	if s.isIndex {
		sl, ok := asSlice(node)
		if !ok {
			return fmt.Errorf("%w: cannot index %T", ErrTypeMismatch, node)
		}
		if s.index >= len(sl) {
			return fmt.Errorf("%w: index [%d] out of range", ErrNotFound, s.index)
		}
		if len(rest) == 0 {
			sl[s.index] = nil
			return nil
		}
		return removeNode(sl[s.index], rest)
	}

	m, ok := asMapRef(node)
	if !ok {
		return fmt.Errorf("%w: cannot delete key %q from %T", ErrTypeMismatch, s.key, node)
	}
	if len(rest) == 0 {
		if _, ok := m.lookup(s.key); !ok {
			return fmt.Errorf("%w: key %q", ErrNotFound, s.key)
		}
		m.remove(s.key)
		return nil
	}
	child, ok := m.lookup(s.key)
	if !ok {
		return fmt.Errorf("%w: key %q", ErrNotFound, s.key)
	}
	return removeNode(child, rest)
}

// Package mapx provides a fluent, chainable API for reading and writing
// arbitrary map[string]interface{} data.
//
// A Wrapper is created with New and exposes chainable setters:
//
//	data := mapx.New(nil).
//		Set("user.name", "Ada").
//		Set("user.age", 36).
//		Set("user.tags[0]", "admin").
//		Data()
//
// Reads navigate dotted paths with optional slice indices and are collected
// through a Value that carries any conversion or lookup error:
//
//	name := mapx.New(data).Get("user.name").String()
//	age := mapx.New(data).Get("user.age").Int()
package mapx

import (
	"errors"
	"fmt"
	"sort"
)

// Errors reported by the package. Use errors.Is to test them.
var (
	ErrNotFound    = errors.New("mapx: not found")
	ErrTypeMismatch = errors.New("mapx: type mismatch")
	ErrInvalidPath = errors.New("mapx: invalid path")
)

// Map is the data shape operated on by the package.
type Map map[string]interface{}

// Wrapper carries a map and the first error encountered while chaining.
// Methods never panic; call Err to inspect the accumulated error.
type Wrapper struct {
	m   Map
	err error
}

// New returns a Wrapper over m. A nil map is replaced with an empty one.
func New(m map[string]interface{}) *Wrapper {
	if m == nil {
		m = map[string]interface{}{}
	}
	return &Wrapper{m: Map(m)}
}

// From is an alias for New.
func From(m map[string]interface{}) *Wrapper { return New(m) }

// Data returns the underlying map.
func (w *Wrapper) Data() map[string]interface{} { return map[string]interface{}(w.m) }

// Err returns the first error encountered while chaining, if any.
func (w *Wrapper) Err() error { return w.err }

// Get resolves path and returns a Value. Missing keys or bad conversions set
// the error on the returned Value rather than panicking.
func (w *Wrapper) Get(path string) *Value {
	if w.err != nil {
		return &Value{err: w.err}
	}
	v, err := lookup(w.m, path)
	return &Value{raw: v, err: err}
}

// Set assigns value at path, creating intermediate maps (and slices when the
// next path segment is an index) as needed. It returns the Wrapper for chaining.
func (w *Wrapper) Set(path string, value interface{}) *Wrapper {
	if w.err != nil {
		return w
	}
	if err := assign(w.m, path, value); err != nil {
		w.err = err
	}
	return w
}

// Merge copies every top-level key of other into the wrapped map.
func (w *Wrapper) Merge(other map[string]interface{}) *Wrapper {
	if w.err != nil {
		return w
	}
	for k, v := range other {
		w.m[k] = v
	}
	return w
}

// Delete removes the value at path. Removing a slice element sets it to nil.
func (w *Wrapper) Delete(path string) *Wrapper {
	if w.err != nil {
		return w
	}
	if err := remove(w.m, path); err != nil {
		w.err = err
	}
	return w
}

// Has reports whether path resolves to a value.
func (w *Wrapper) Has(path string) bool {
	if w.err != nil {
		return false
	}
	_, err := lookup(w.m, path)
	return err == nil
}

// Len returns the number of top-level keys.
func (w *Wrapper) Len() int { return len(w.m) }

// Keys returns the top-level keys in sorted order.
func (w *Wrapper) Keys() []string {
	keys := make([]string, 0, len(w.m))
	for k := range w.m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Clone returns a Wrapper over a deep copy of the wrapped map.
func (w *Wrapper) Clone() *Wrapper {
	return &Wrapper{m: Map(deepCopyMap(w.m))}
}

// String implements fmt.Stringer.
func (w *Wrapper) String() string { return fmt.Sprintf("%v", w.m) }

func deepCopy(v interface{}) interface{} {
	switch t := v.(type) {
	case map[string]interface{}:
		return deepCopyMap(t)
	case Map:
		return Map(deepCopyMap(t))
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = deepCopy(e)
		}
		return out
	default:
		return v
	}
}

func deepCopyMap(m map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(m))
	for k, v := range m {
		out[k] = deepCopy(v)
	}
	return out
}

package mapx

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// Value is a resolved value paired with any lookup or conversion error.
// Accessor methods return the zero value on error and record it in Err.
type Value struct {
	raw interface{}
	err error
}

// Raw returns the underlying value.
func (v *Value) Raw() interface{} { return v.raw }

// Interface returns the underlying value. It is an alias for Raw.
func (v *Value) Interface() interface{} { return v.raw }

// Err returns the lookup or conversion error, if any.
func (v *Value) Err() error { return v.err }

// Exists reports whether a value was resolved without error.
func (v *Value) Exists() bool { return v != nil && v.err == nil }

// IsNil reports whether the resolved value is nil.
func (v *Value) IsNil() bool { return v.raw == nil }

// Get navigates deeper into the current value, which must be a map.
func (v *Value) Get(path string) *Value {
	if v.err != nil {
		return v
	}
	m, ok := asMapRef(v.raw)
	if !ok {
		return &Value{err: fmt.Errorf("%w: cannot navigate %T", ErrTypeMismatch, v.raw)}
	}
	out, err := lookup(Map(map[string]interface{}(nil)), "")
	_ = out
	_ = m
	return lookupFrom(m, path)
}

func lookupFrom(m mapRef, path string) *Value {
	segs, err := parsePath(path)
	if err != nil {
		return &Value{err: err}
	}
	var cur interface{} = map[string]interface{}(nil)
	_ = cur
	// walk using the same rules as lookup but starting from a mapRef
	curr := interface{}(nil)
	var root map[string]interface{}
	switch mm := m.(type) {
	case stdMap:
		root = map[string]interface{}(mm)
	case namedMap:
		root = map[string]interface{}(mm)
	default:
		return &Value{err: fmt.Errorf("%w: bad map reference", ErrTypeMismatch)}
	}
	curr = root
	for _, s := range segs {
		if s.isIndex {
			sl, ok := asSlice(curr)
			if !ok {
				return &Value{err: fmt.Errorf("%w: expected slice for index [%d], got %T", ErrTypeMismatch, s.index, curr)}
			}
			if s.index >= len(sl) {
				return &Value{err: fmt.Errorf("%w: index [%d] out of range", ErrNotFound, s.index)}
			}
			curr = sl[s.index]
		} else {
			ref, ok := asMapRef(curr)
			if !ok {
				return &Value{err: fmt.Errorf("%w: expected map for key %q, got %T", ErrTypeMismatch, s.key, curr)}
			}
			val, ok := ref.lookup(s.key)
			if !ok {
				return &Value{err: fmt.Errorf("%w: key %q", ErrNotFound, s.key)}
			}
			curr = val
		}
	}
	return &Value{raw: curr}
}

// String returns the value as a string.
func (v *Value) String() string {
	if v.err != nil || v.raw == nil {
		return ""
	}
	switch s := v.raw.(type) {
	case string:
		return s
	case []byte:
		return string(s)
	default:
		return fmt.Sprint(v.raw)
	}
}

// Int returns the value as an int.
func (v *Value) Int() int {
	n, err := v.int64()
	if err != nil {
		v.fail(err)
		return 0
	}
	return int(n)
}

// Int64 returns the value as an int64.
func (v *Value) Int64() int64 {
	n, err := v.int64()
	if err != nil {
		v.fail(err)
		return 0
	}
	return n
}

// Float64 returns the value as a float64.
func (v *Value) Float64() float64 {
	f, err := v.float64()
	if err != nil {
		v.fail(err)
		return 0
	}
	return f
}

// Bool returns the value as a bool.
func (v *Value) Bool() bool {
	if v.err != nil {
		return false
	}
	switch b := v.raw.(type) {
	case bool:
		return b
	case string:
		parsed, err := strconv.ParseBool(strings.TrimSpace(b))
		if err != nil {
			v.fail(fmt.Errorf("%w: cannot convert %q to bool", ErrTypeMismatch, b))
			return false
		}
		return parsed
	case int:
		return b != 0
	case int64:
		return b != 0
	case float64:
		return b != 0
	default:
		v.fail(fmt.Errorf("%w: cannot convert %T to bool", ErrTypeMismatch, v.raw))
		return false
	}
}

// Map returns the value as a map[string]interface{}.
func (v *Value) Map() map[string]interface{} {
	if v.err != nil {
		return nil
	}
	switch m := v.raw.(type) {
	case map[string]interface{}:
		return m
	case Map:
		return map[string]interface{}(m)
	default:
		v.fail(fmt.Errorf("%w: cannot convert %T to map", ErrTypeMismatch, v.raw))
		return nil
	}
}

// Slice returns the value as a []interface{}.
func (v *Value) Slice() []interface{} {
	if v.err != nil {
		return nil
	}
	if s, ok := asSlice(v.raw); ok {
		return s
	}
	v.fail(fmt.Errorf("%w: cannot convert %T to slice", ErrTypeMismatch, v.raw))
	return nil
}

// Or returns the current value if valid, otherwise fallback.
func (v *Value) Or(fallback interface{}) *Value {
	if v.err != nil || v.raw == nil {
		return &Value{raw: fallback}
	}
	return v
}

func (v *Value) fail(err error) {
	if v.err == nil {
		v.err = err
	}
}

func (v *Value) int64() (int64, error) {
	if v.err != nil {
		return 0, v.err
	}
	if v.raw == nil {
		return 0, fmt.Errorf("%w: nil value", ErrTypeMismatch)
	}
	switch n := v.raw.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case json.Number:
		return n.Int64()
	case string:
		s := strings.TrimSpace(n)
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i, nil
		}
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return int64(f), nil
		}
	}
	return 0, fmt.Errorf("%w: cannot convert %T to int64", ErrTypeMismatch, v.raw)
}

func (v *Value) float64() (float64, error) {
	if v.err != nil {
		return 0, v.err
	}
	if v.raw == nil {
		return 0, fmt.Errorf("%w: nil value", ErrTypeMismatch)
	}
	switch n := v.raw.(type) {
	case float64:
		return n, nil
	case float32:
		return float64(n), nil
	case int:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case json.Number:
		return n.Float64()
	case string:
		f, err := strconv.ParseFloat(strings.TrimSpace(n), 64)
		if err == nil {
			return f, nil
		}
	}
	if i, err := v.int64(); err == nil {
		return float64(i), nil
	}
	return 0, fmt.Errorf("%w: cannot convert %T to float64", ErrTypeMismatch, v.raw)
}

